// Lee TOP keywords y competidores desde env vars (con prefijo TOROMAC_).
// Solo analiza las 5 primeras keywords por ejecución para controlar coste de
// API. El cron es semanal, así que en ~5 semanas cubre las 26 keywords.
const kwsRaw = $env.TOROMAC_TARGET_KEYWORDS_ES || '';
const compRaw = $env.TOROMAC_COMPETITORS || '';
const keywords = kwsRaw.split(',').map(k => k.trim()).filter(Boolean).slice(0, 5);
const competitors = compRaw.split(',').map(c => c.trim().toLowerCase()).filter(Boolean);
if (!keywords.length) throw new Error('TOROMAC_TARGET_KEYWORDS_ES vacía');
if (!competitors.length) throw new Error('TOROMAC_COMPETITORS vacía');
return keywords.map(k => ({ json: { keyword: k, competitors } }));

// Analiza el SERP: encuentra posición de Toromac y de competidores.
// Si un competidor está mejor posicionado que Toromac (o Toromac no aparece),
// marca esa keyword como gap.
const serp = $input.first().json;
const keyword = $('Build Keyword Batch').item.json.keyword;
const competitors = $('Build Keyword Batch').item.json.competitors;
const organic = serp.organic || [];

const findDomain = (d) => organic.find(r => (r.link || '').toLowerCase().includes(d));
const toromacResult = findDomain('toromac.com');
const toromacPos = toromacResult ? toromacResult.position : null;

const competitorHits = competitors
  .map(c => ({ domain: c, result: findDomain(c) }))
  .filter(c => c.result)
  .map(c => ({ domain: c.domain, position: c.result.position, url: c.result.link, title: c.result.title, snippet: c.result.snippet }));

// El competidor mejor posicionado (menor posición numérica = mejor)
competitorHits.sort((a, b) => a.position - b.position);
const topCompetitor = competitorHits[0] || null;

// Hay gap si: Toromac no aparece, o aparece pero un competidor está mejor.
const hasGap = topCompetitor && (toromacPos === null || topCompetitor.position < toromacPos);

return [{
  json: {
    keyword,
    toromacPos,
    toromacUrl: toromacResult?.link || null,
    topCompetitor,
    competitorHits,
    hasGap,
  }
}];

