const raw = $input.first().json;
const text = raw.content?.[0]?.text || raw.message?.content?.[0]?.text || '';
let jsonStr = text.trim();
const fence = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
if (fence) jsonStr = fence[1].trim();
const first = jsonStr.indexOf('{');
const last = jsonStr.lastIndexOf('}');
if (first !== -1 && last !== -1) jsonStr = jsonStr.slice(first, last + 1);
let analysis;
try { analysis = JSON.parse(jsonStr); } catch (e) { throw new Error('Analysis parse failed: ' + e.message); }
const gap = $('Analyze SERP').item.json;
return [{ json: { ...gap, analysis } }];

// Pre-computa todos los valores como JS planos para evitar el bug v4.5
// donde el `=` de las expresiones se cuela en el cell de Sheets.
const gap = $('Parse Analysis').item.json;
const a = gap.analysis;
const now = new Date().toISOString();
return [{
  json: {
    // Campos para competitor-findings
    fecha: now,
    keyword: gap.keyword,
    competidor: gap.topCompetitor.domain,
    posicion_competidor: gap.topCompetitor.position,
    posicion_toromac: gap.toromacPos ?? 'no aparece',
    nuestra_url: gap.toromacUrl ?? '',
    analisis: a.analisis,
    accion_propuesta: a.accion_propuesta.tipo + ': ' + a.accion_propuesta.descripcion,
    asignado_a: a.accion_propuesta.asignado_a,
    estado: 'pendiente',
    // Campos para seo-changelog
    timestamp: now,
    agente: 'competitor',
    accion: 'gap_detected:' + gap.keyword,
    target: gap.topCompetitor.domain,
    resultado: 'success'
  }
}];

